/* ============================================================
   PARSE + MERGE
   ============================================================ */
(function(){
  const parseBloco = (raw) => raw.split('\n')
    .map(l => l.trim())
    .filter(l => l && !l.startsWith('#'))
    .map(l => {
      const partes = l.split(/(?<!\\)\|/).map(p => p.replace(/\\\|/g, '|'));
      const [n, c, e, cl, t, a, co, d, ds, up] = partes;
      return {
        n,
        c: parseInt(c, 10) || 0,
        e,
        cl: cl ? cl.split(',').map(s => s.trim()).filter(Boolean) : [],
        t, a, co, d,
        ds: (ds || '').replace(/\\n/g, '\n'),
        up: (up || '').replace(/\\n/g, '\n'),
      };
    });

  window.DND_DATA = window.DND_DATA || {};
  window.DND_DATA.SPELLS = (window.DND_DATA.SPELLS || []).concat(parseBloco(BLOCO03_RAW));
  window.SPELLS = window.DND_DATA.SPELLS;

  console.log('[DND] Bloco 3 carregado. Total de magias:', window.DND_DATA.SPELLS.length);
})();